
import "dotenv/config";
import express from "express";
import cors from "cors";
import jwt from "jsonwebtoken";
import { createClient } from "@supabase/supabase-js";

const app = express();

app.use(cors());
app.use(express.json({ limit: "2mb" }));

const {
  SUPABASE_URL,
    SUPABASE_SERVICE_ROLE_KEY,
      JWT_SECRET,
        ADMIN_USERNAME,
          ADMIN_PASSWORD
          } = process.env;

          const db = SUPABASE_URL && SUPABASE_SERVICE_ROLE_KEY
            ? createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY)
              : null;

              const ready = (req, res, next) => {
                if (!db) {
                    return res.status(503).json({ error: "Server belum dikonfigurasi." });
                      }
                        next();
                        };

                        const auth = (req, res, next) => {
                          try {
                              const token = (req.headers.authorization || "").replace(/^Bearer /, "");
                                  req.user = jwt.verify(token, JWT_SECRET);
                                      next();
                                        } catch {
                                            res.status(401).json({ error: "Silakan login kembali." });
                                              }
                                              };

                                              app.get("/api/health", (req, res) => {
                                                res.json({ ok: true, configured: !!db });
                                                });

                                                app.post("/api/login", ready, async (req, res) => {
                                                  const { username, password } = req.body || {};

                                                    if (username !== ADMIN_USERNAME || password !== ADMIN_PASSWORD) {
                                                        return res.status(401).json({ error: "Username atau password salah." });
                                                          }

                                                            const token = jwt.sign(
                                                                { username, role: "staff" },
                                                                    JWT_SECRET,
                                                                        { expiresIn: "12h" }
                                                                          );

                                                                            res.json({ token, username });
                                                                            });

                                                                            app.get("/api/menu", ready, async (req, res) => {
                                                                              const { data, error } = await db
                                                                                  .from("menu_items")
                                                                                      .select("*")
                                                                                          .eq("is_available", true)
                                                                                              .order("category")
                                                                                                  .order("name");

                                                                                                    if (error) return res.status(500).json({ error: error.message });
                                                                                                      res.json(data || []);
                                                                                                      });

                                                                                                      app.post("/api/orders", ready, async (req, res) => {
                                                                                                        const {
                                                                                                            table_no,
                                                                                                                customer_name,
                                                                                                                    payment_method,
                                                                                                                        notes,
                                                                                                                            items
                                                                                                                              } = req.body || {};

                                                                                                                                const table = Number(table_no);

                                                                                                                                  if (!Number.isInteger(table) || table < 1 || table > 20) {
                                                                                                                                      return res.status(400).json({ error: "Nomor meja tidak valid." });
                                                                                                                                        }

                                                                                                                                          if (!Array.isArray(items) || !items.length) {
                                                                                                                                              return res.status(400).json({ error: "Keranjang masih kosong." });
                                                                                                                                                }

                                                                                                                                                  if (!["cash", "qris"].includes(payment_method)) {
                                                                                                                                                      return res.status(400).json({ error: "Metode pembayaran tidak valid." });
                                                                                                                                                        }

                                                                                                                                                          const ids = items.map(x => x.menu_id);

                                                                                                                                                            const { data: menus, error: menuErr } = await db
                                                                                                                                                                .from("menu_items")
                                                                                                                                                                    .select("id,name,price,is_available")
                                                                                                                                                                        .in("id", ids);

                                                                                                                                                                          if (menuErr || !menus?.length) {
                                                                                                                                                                              return res.status(400).json({ error: "Menu tidak ditemukan." });
                                                                                                                                                                                }

                                                                                                                                                                                  let total = 0;
                                                                                                                                                                                    const lines = [];

                                                                                                                                                                                      for (const item of items) {
                                                                                                                                                                                          const menu = menus.find(m => m.id === item.menu_id);
                                                                                                                                                                                              const qty = Math.floor(Number(item.quantity));

                                                                                                                                                                                                  if (!menu || !menu.is_available || !Number.isInteger(qty) || qty < 1 || qty > 99) {
                                                                                                                                                                                                        continue;
                                                                                                                                                                                                            }

                                                                                                                                                                                                                total += Number(menu.price) * qty;

                                                                                                                                                                                                                    lines.push({
                                                                                                                                                                                                                          menu_id: menu.id,
                                                                                                                                                                                                                                menu_name: menu.name,
                                                                                                                                                                                                                                      unit_price: menu.price,
                                                                                                                                                                                                                                            quantity: qty,
                                                                                                                                                                                                                                                  note: String(item.note || "").slice(0, 250)
                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                          if (!lines.length) {
                                                                                                                                                                                                                                                              return res.status(400).json({ error: "Tidak ada menu yang tersedia." });
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                  const code = "WD" + Date.now().toString().slice(-8);

                                                                                                                                                                                                                                                                    const { data: order, error } = await db
                                                                                                                                                                                                                                                                        .from("orders")
                                                                                                                                                                                                                                                                            .insert({
                                                                                                                                                                                                                                                                                  order_code: code,
                                                                                                                                                                                                                                                                                        table_no: table,
                                                                                                                                                                                                                                                                                              customer_name: String(customer_name || "").slice(0, 80),
                                                                                                                                                                                                                                                                                                    payment_method,
                                                                                                                                                                                                                                                                                                          notes: String(notes || "").slice(0, 500),
                                                                                                                                                                                                                                                                                                                total,
                                                                                                                                                                                                                                                                                                                      order_status: "new",
                                                                                                                                                                                                                                                                                                                            payment_status: "unpaid"
                                                                                                                                                                                                                                                                                                                                })
                                                                                                                                                                                                                                                                                                                                    .select()
                                                                                                                                                                                                                                                                                                                                        .single();

                                                                                                                                                                                                                                                                                                                                          if (error) return res.status(500).json({ error: error.message });

                                                                                                                                                                                                                                                                                                                                            const { error: itemErr } = await db
                                                                                                                                                                                                                                                                                                                                                .from("order_items")
                                                                                                                                                                                                                                                                                                                                                    .insert(lines.map(x => ({ ...x, order_id: order.id })));

                                                                                                                                                                                                                                                                                                                                                      if (itemErr) {
                                                                                                                                                                                                                                                                                                                                                          await db.from("orders").delete().eq("id", order.id);
                                                                                                                                                                                                                                                                                                                                                              return res.status(500).json({ error: itemErr.message });
                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                  res.status(201).json({ ...order, items: lines });
                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                  app.get("/api/orders", ready, auth, async (req, res) => {
                                                                                                                                                                                                                                                                                                                                                                    let q = db
                                                                                                                                                                                                                                                                                                                                                                        .from("orders")
                                                                                                                                                                                                                                                                                                                                                                            .select("*,order_items(*)")
                                                                                                                                                                                                                                                                                                                                                                                .order("created_at", { ascending: false })
                                                                                                                                                                                                                                                                                                                                                                                    .limit(150);

                                                                                                                                                                                                                                                                                                                                                                                      if (req.query.status && req.query.status !== "all") {
                                                                                                                                                                                                                                                                                                                                                                                          q = q.eq("order_status", req.query.status);
                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                              const { data, error } = await q;

                                                                                                                                                                                                                                                                                                                                                                                                if (error) return res.status(500).json({ error: error.message });
                                                                                                                                                                                                                                                                                                                                                                                                  res.json(data || []);
                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                  app.patch("/api/orders/:id", ready, auth, async (req, res) => {
                                                                                                                                                                                                                                                                                                                                                                                                    const allowed = {};

                                                                                                                                                                                                                                                                                                                                                                                                      if (["new", "accepted", "cooking", "ready", "completed", "cancelled"].includes(req.body.order_status)) {
                                                                                                                                                                                                                                                                                                                                                                                                          allowed.order_status = req.body.order_status;
                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                              if (["unpaid", "paid"].includes(req.body.payment_status)) {
                                                                                                                                                                                                                                                                                                                                                                                                                  allowed.payment_status = req.body.payment_status;
                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                      if (!Object.keys(allowed).length) {
                                                                                                                                                                                                                                                                                                                                                                                                                          return res.status(400).json({ error: "Perubahan tidak valid." });
                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                              const { data, error } = await db
                                                                                                                                                                                                                                                                                                                                                                                                                                  .from("orders")
                                                                                                                                                                                                                                                                                                                                                                                                                                      .update(allowed)
                                                                                                                                                                                                                                                                                                                                                                                                                                          .eq("id", req.params.id)
                                                                                                                                                                                                                                                                                                                                                                                                                                              .select()
                                                                                                                                                                                                                                                                                                                                                                                                                                                  .single();

                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (error) return res.status(500).json({ error: error.message });
                                                                                                                                                                                                                                                                                                                                                                                                                                                      res.json(data);
                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                      app.get("/api/admin/menu", ready, auth, async (req, res) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { data, error } = await db
                                                                                                                                                                                                                                                                                                                                                                                                                                                            .from("menu_items")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                .select("*")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .order("category")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .order("name");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (error) return res.status(500).json({ error: error.message });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            res.json(data || []);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            app.post("/api/admin/menu", ready, auth, async (req, res) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const { name, category, price, description, image_url, is_available } = req.body || {};

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!name || !category || !Number.isFinite(Number(price)) || Number(price) < 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return res.status(400).json({ error: "Nama, kategori, dan harga wajib diisi." });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { data, error } = await db
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .from("menu_items")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .insert({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            category,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  price: Number(price),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        description: description || "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              image_url: image_url || "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    is_available: is_available !== false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .select()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .single();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (error) return res.status(500).json({ error: error.message });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    res.status(201).json(data);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    app.patch("/api/admin/menu/:id", ready, auth, async (req, res) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const patch = {};

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (const k of ["name", "category", "description", "image_url", "is_available"]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (req.body[k] !== undefined) patch[k] = req.body[k];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (req.body.price !== undefined) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    patch.price = Number(req.body.price);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { data, error } = await db
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .from("menu_items")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .update(patch)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .eq("id", req.params.id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .select()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .single();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (error) return res.status(500).json({ error: error.message });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                res.json(data);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                app.delete("/api/admin/menu/:id", ready, auth, async (req, res) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const { error } = await db
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .from("menu_items")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .delete()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .eq("id", req.params.id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (error) return res.status(500).json({ error: error.message });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  res.json({ ok: true });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  app.get("/api/admin/report", ready, auth, async (req, res) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const start = new Date();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      start.setHours(0, 0, 0, 0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { data, error } = await db
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .from("orders")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .select("total,payment_status,order_status,created_at")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .gte("created_at", start.toISOString());

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (error) return res.status(500).json({ error: error.message });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const rows = data || [];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          res.json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              count: rows.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  revenue: rows
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .filter(x => x.payment_status === "paid")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .reduce((s, x) => s + Number(x.total), 0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  pending: rows.filter(x => x.payment_status === "unpaid").length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    app.use(express.static("dist"));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    app.get("*", (req, res, next) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (req.path.startsWith("/api/")) return next();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        res.sendFile(process.cwd() + "/dist/index.html");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const port = process.env.PORT || 4000;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        app.listen(port, () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.log(`OMAH W-DOS server berjalan di port ${port}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          